// ============================================================================
// 1. EMBEDDED RAMAYANA VISUAL ASSETS (Inlined via Step 3 Base64 Pipeline)
// ============================================================================
const HERO_BG_IMG = "data:image/jpeg;base64,";
const RAMA_IMG = "data:image/jpeg;base64,";
const SITA_IMG = "data:image/jpeg;base64,";
const HANUMAN_IMG = "data:image/jpeg;base64,";
