// Helper to generate ornate SVG data URIs for the remaining 15 Ramayana characters
function createCharacterCrestSvg(
  name: string,
  title: string,
  bgStart: string,
  bgEnd: string,
  accent: string,
  emblemType: 'crown' | 'bow' | 'mace' | 'lotus' | 'eagle' | 'shield' | 'sword' | 'chariot'
): string {
  const emblemPaths: Record<string, string> = {
    crown: `<path d="M55 135 L75 85 L100 112 L120 72 L140 112 L165 85 L185 135 Z" fill="${accent}" stroke="#FFF8E7" stroke-width="3"/><circle cx="120" cy="64" r="7" fill="#FFF8E7"/>`,
    bow: `<path d="M85 65 C150 95, 150 145, 85 175" fill="none" stroke="${accent}" stroke-width="6" stroke-linecap="round"/><line x1="85" y1="65" x2="85" y2="175" stroke="#FFF8E7" stroke-width="2.5"/><line x1="70" y1="120" x2="155" y2="120" stroke="${accent}" stroke-width="4"/><polygon points="162,120 146,112 146,128" fill="#FFF8E7"/>`,
    mace: `<circle cx="120" cy="95" r="28" fill="${accent}" stroke="#FFF8E7" stroke-width="3"/><rect x="114" y="123" width="12" height="55" rx="5" fill="${accent}" stroke="#FFF8E7" stroke-width="2"/>`,
    lotus: `<path d="M120 70 C138 95, 138 125, 120 145 C102 125, 102 95, 120 70 Z" fill="${accent}" stroke="#FFF8E7" stroke-width="2.5"/><path d="M120 145 C148 135, 165 110, 152 88 C136 102, 132 120, 120 145 Z" fill="${accent}" opacity="0.85"/><path d="M120 145 C92 135, 75 110, 88 88 C104 102, 108 120, 120 145 Z" fill="${accent}" opacity="0.85"/>`,
    eagle: `<path d="M65 115 Q95 75 120 105 Q145 75 175 115 Q145 130 120 150 Q95 130 65 115 Z" fill="${accent}" stroke="#FFF8E7" stroke-width="2.5"/><circle cx="120" cy="85" r="10" fill="#FFF8E7"/>`,
    shield: `<path d="M85 75 L155 75 L155 118 C155 148, 120 168, 120 168 C120 168, 85 148, 85 118 Z" fill="${accent}" stroke="#FFF8E7" stroke-width="3"/><circle cx="120" cy="115" r="14" fill="#0B1528" stroke="#FFF8E7" stroke-width="2"/>`,
    sword: `<path d="M120 62 L130 132 L110 132 Z" fill="#FFF8E7" stroke="${accent}" stroke-width="2"/><rect x="96" y="132" width="48" height="8" rx="4" fill="${accent}"/><rect x="115" y="140" width="10" height="28" rx="3" fill="${accent}"/>`,
    chariot: `<circle cx="120" cy="115" r="34" fill="none" stroke="${accent}" stroke-width="6"/><circle cx="120" cy="115" r="10" fill="#FFF8E7"/><line x1="120" y1="81" x2="120" y2="149" stroke="${accent}" stroke-width="3"/><line x1="86" y1="115" x2="154" y2="115" stroke="${accent}" stroke-width="3"/><line x1="96" y1="91" x2="144" y2="139" stroke="${accent}" stroke-width="3"/><line x1="144" y1="91" x2="96" y2="139" stroke="${accent}" stroke-width="3"/>`
  };
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 240">
    <defs>
      <radialGradient id="g" cx="50%" cy="40%" r="65%">
        <stop offset="0%" stop-color="${bgStart}"/>
        <stop offset="100%" stop-color="${bgEnd}"/>
      </radialGradient>
    </defs>
    <rect width="240" height="240" rx="28" fill="url(#g)"/>
    <rect x="10" y="10" width="220" height="220" rx="22" fill="none" stroke="${accent}" stroke-width="2.5" stroke-dasharray="6 4" opacity="0.75"/>
    <circle cx="120" cy="115" r="58" fill="#0B1528" fill-opacity="0.45" stroke="${accent}" stroke-width="2"/>
    ${emblemPaths[emblemType] || emblemPaths.crown}
    <text x="120" y="200" text-anchor="middle" fill="#FFF8E7" font-family="Georgia, serif" font-weight="bold" font-size="20" letter-spacing="1">${name.toUpperCase()}</text>
    <text x="120" y="219" text-anchor="middle" fill="${accent}" font-family="sans-serif" font-size="11" letter-spacing="1.5">${title.toUpperCase()}</text>
  </svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

// ============================================================================
// 2. TYPES & INTERFACES (Mirroring Normalized 16-Table PostgreSQL Schema)
// ============================================================================
export type UserRole = 'guest' | 'player' | 'moderator' | 'admin';
export type PlayerType = 'human' | 'bot' | 'spectator';
export type ConnectionStatus = 'online' | 'reconnecting' | 'disconnected';
export type RoomStatus = 'waiting' | 'in_progress' | 'completed' | 'closed';
export type RoundStatus = 'distributing' | 'rama_revealed' | 'discussion' | 'guessing' | 'completed';
export type BotPersonality =
  | 'smart_observer'
  | 'confident_bluffer'
  | 'silent_player'
  | 'funny_player'
  | 'aggressive_guesser'
  | 'strategic_player';

export type AdPlacement =
  | 'home_banner'
  | 'home_promo_card'
  | 'waiting_room_banner'
  | 'game_result_screen'
  | 'leaderboard_page'
  | 'footer_banner';

export type AdType = 'image' | 'promo_text' | 'external_url' | 'sandboxed_snippet';

export interface Profile {
  id: string;
  display_name: string;
  avatar_url: string;
  role: UserRole;
  email?: string;
  is_authenticated: boolean;
  is_disabled: boolean;
  created_at: string;
}

export interface CharacterDef {
  id: string;
  slug: string;
  name: string;
  description: string;
  image_url: string;
  default_score: number;
  category: 'Royal Family' | 'Vanara Sena' | 'Lanka Court' | 'Sacred Allies' | 'Custom';
  is_mandatory?: boolean;
  is_active: boolean;
}

export interface RoomSettings {
  max_rounds: number;
  unlimited_rounds: boolean;
  is_private: boolean;
  allow_bots: boolean;
  allow_spectators: boolean;
  chat_enabled: boolean;
  reactions_enabled: boolean;
  turn_timer_seconds: number;
  rama_correct_points: number;
  sita_escape_points: number;
}

export interface RoomPlayer {
  id: string;
  room_id: string;
  user_id: string;
  display_name: string;
  avatar_url: string;
  player_type: PlayerType;
  bot_personality?: BotPersonality;
  is_ready: boolean;
  connection_status: ConnectionStatus;
  reconnect_token: string;
  joined_at: string;
}

export interface RoomCharacterConfig {
  character_id: string;
  assigned_score: number;
}

export interface CharacterAssignment {
  id: string;
  round_id: string;
  player_id: string;
  character_id: string;
  assigned_score: number;
}

export interface RoundScore {
  id: string;
  round_id: string;
  player_id: string;
  points_earned: number;
}

export interface RoundRecord {
  id: string;
  session_id: string;
  round_number: number;
  status: RoundStatus;
  rama_player_id: string;
  // sita_player_id is kept inside backend vault and only projected to client when status === 'completed'
  sita_player_id_revealed?: string;
  guessed_player_id?: string;
  is_correct?: boolean;
  timer_remaining: number;
  created_at: string;
  completed_at?: string;
}

export interface PlayerTotal {
  player_id: string;
  display_name: string;
  avatar_url: string;
  player_type: PlayerType;
  total_score: number;
  last_round_score: number;
  previous_rank: number;
  current_rank: number;
  rama_rounds: number;
  rama_wins: number;
  sita_rounds: number;
  sita_escapes: number;
}

export interface RoomMessage {
  id: string;
  room_id: string;
  session_id: string;
  player_id: string;
  player_name: string;
  message: string;
  message_type: 'chat' | 'system' | 'join_leave' | 'round_start' | 'guess' | 'result';
  created_at: string;
}

export interface FloatingReaction {
  id: string;
  room_id: string;
  player_id: string;
  player_name: string;
  reaction: string;
  created_at: number;
}

export interface CompletedSessionHistory {
  id: string;
  room_name: string;
  room_code: string;
  started_at: string;
  ended_at: string;
  rounds_played: number;
  winner_name: string;
  winner_score: number;
  standings: PlayerTotal[];
  round_summaries: {
    round_number: number;
    rama_name: string;
    sita_name: string;
    guessed_name: string;
    is_correct: boolean;
    scores: { player_name: string; character_name: string; points: number }[];
  }[];
}

export interface Advertisement {
  id: string;
  title: string;
  ad_type: AdType;
  placement: AdPlacement;
  image_url?: string;
  destination_url: string;
  promo_text: string;
  ad_code?: string;
  is_active: boolean;
  priority: number;
  start_at: string;
  end_at: string;
  impressions: number;
  clicks: number;
}

export interface AdminLogEntry {
  id: string;
  admin_name: string;
  action: string;
  target_type: string;
  target_id: string;
  created_at: string;
}

